/**
 * Built-in scenarios (tasks A.6). The JSON files are generated by `gen_scenarios.py`
 * (fake data); `index.test.ts` checks every tree against the sandbox invariants.
 */
import type { Scenario } from '../fsTypes.ts';
import messyDownloads from './messy-downloads.json';
import cameraPhotos from './camera-photos.json';
import projectTree from './project-tree.json';
import nightlyLogs from './nightly-logs.json';

/** JSON imports widen literal types (`"folder"` → string), so they are asserted here and verified by tests. */
const asScenario = (json: unknown): Scenario => json as Scenario;

export const SCENARIOS: Scenario[] = [
  asScenario(messyDownloads),
  asScenario(cameraPhotos),
  asScenario(projectTree),
  asScenario(nightlyLogs),
];

export function getScenario(id: string): Scenario | undefined {
  return SCENARIOS.find((s) => s.id === id);
}
